#include <cassert>
#include <cstddef>
#include <vector>

auto make_moving_average(std::size_t window) {
  assert(window > 0);
  return [buf = std::vector<double>(window, 0.0),
          idx = std::size_t{0},
          count = std::size_t{0},
          sum = 0.0](double x) mutable {
    sum += x - buf[idx];          // drop oldest, add newest
    buf[idx] = x;
    if (++idx == buf.size()) idx = 0;   // avoid % in hot path
    if (count < buf.size()) ++count;
    return sum / static_cast<double>(count);
  };
}
// Note: a running sum accumulates rounding error over long runs;
// recompute sum from buf periodically or use Kahan summation.

